/// The class overrides `updateIndirectNeighbourShapes` (redstone wire), so a place changes
/// shapes two cells away.
pub fn indirect_shape_block(kind: BlockKind) -> bool {
    matches!(
        kind,
        BlockKind::Piston |
        BlockKind::RedstoneWire |
        BlockKind::StickyPiston
    )
}
